"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[81210],{90798:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"JumpDriveConfig","desc":"Single tuning surface for the Jump Drive: bench interaction, charge values,\\nphase durations, the biome registry, and arrival rewards. Edit gameplay here,\\nnever in manager or controller code.\\n\\nStudio setup required:\\n  1. The bench is the `PowerCore` Model (also the TrainEngine), tagged\\n     `JumpDriveBench` with its PrimaryPart set.\\n  2. Give it a BasePart `JumpPromptPart` holding a ProximityPrompt (key F, opens the GUI).\\n  3. No `DepositPromptPart`: charging happens in the panel (hold the JumpButton).\\n  4. `ReplicatedStorage/JumpDriveVfx/Wormhole`: the Art Place black hole Model\\n     (PrimaryPart `BallPartCenter`, every part Anchored and non-colliding). It\\n     holds the `BlackOrb` spheres and the `TeleportVFX` speed-line Part, whose\\n     emitter Acceleration points along +X (toward the train back).\\n  5. `StarterGui/JumpDriveGui` and `StarterGui/PartyVoteGui` (ScreenGuis, Enabled = false, ResetOnSpawn = false).","source":{"line":21,"path":"src/ReplicatedStorage/SharedModules/Configs/JumpDriveConfig.luau"}}')}}]);